package com.integrydt.backend.controller;

import org.springframework.dao.DuplicateKeyException;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.net.URI;import java.util.*;

@RestController @RequestMapping("/api/v1/admin/gadgets") @PreAuthorize("hasAuthority('PERM_roles.manage')")
public class GadgetsAdminController {private final JdbcTemplate db;public GadgetsAdminController(JdbcTemplate d){db=d;}
 public record GadgetUpsert(String code,String name,String description,String riskLevel,Boolean enabled){} public record VersionCreate(String version,String platform,String architecture,String sdkProtocolVersion,String minClientVersion,String maxClientVersion){}
 @GetMapping public Object list(){return db.queryForList("SELECT CAST(g.id AS CHAR) id,g.code,g.name,g.description,g.publisher,g.enabled,g.risk_level riskLevel,(SELECT COUNT(*) FROM gadget_versions gv WHERE gv.gadget_id=g.id) versionCount FROM gadgets g ORDER BY g.name");}
 @PostMapping public ResponseEntity<?> create(@RequestBody GadgetUpsert r){if(!Set.of("low","medium","high","critical").contains(r.riskLevel()))return ResponseEntity.badRequest().body(Map.of("error","invalid_risk_level"));String id=UUID.randomUUID().toString();try{db.update("INSERT INTO gadgets(id,code,name,description,enabled,risk_level) VALUES(?,?,?,?,?,?)",id,r.code(),r.name(),r.description(),r.enabled()==null||r.enabled(),r.riskLevel());return ResponseEntity.created(URI.create("/api/v1/admin/gadgets/"+id)).body(Map.of("id",id));}catch(DuplicateKeyException e){return ResponseEntity.status(409).body(Map.of("error","gadget_code_exists"));}}
 @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable String id,@RequestBody GadgetUpsert r){int n=db.update("UPDATE gadgets SET code=?,name=?,description=?,enabled=?,risk_level=? WHERE id=?",r.code(),r.name(),r.description(),r.enabled()==null||r.enabled(),r.riskLevel(),id);return n==0?ResponseEntity.notFound().build():ResponseEntity.noContent().build();}
 @DeleteMapping("/{id}") public ResponseEntity<?> disable(@PathVariable String id){return db.update("UPDATE gadgets SET enabled=0 WHERE id=?",id)==0?ResponseEntity.notFound().build():ResponseEntity.noContent().build();}
 @GetMapping("/{id}/versions") public Object versions(@PathVariable String id){return db.queryForList("SELECT CAST(id AS CHAR) id,version,sdk_protocol_version sdkProtocolVersion,platform,architecture,storage_key storageKey,package_size packageSize,sha256,entrypoint,status,published_at publishedAt,revoked_at revokedAt FROM gadget_versions WHERE gadget_id=? ORDER BY created_at DESC",id);}
 @PostMapping("/{id}/versions") public ResponseEntity<?> createVersion(@PathVariable String id,@RequestBody VersionCreate r){Integer n=db.queryForObject("SELECT COUNT(*) FROM gadgets WHERE id=?",Integer.class,id);if(n==null||n==0)return ResponseEntity.notFound().build();String vid=UUID.randomUUID().toString();try{db.update("INSERT INTO gadget_versions(id,gadget_id,version,sdk_protocol_version,platform,architecture,storage_key,package_size,sha256,min_client_version,max_client_version,status) VALUES(?,?,?,?,?,?,'pending',0,REPEAT('0',64),?,?,'draft')",vid,id,r.version(),or(r.sdkProtocolVersion(),"1"),or(r.platform(),"windows"),or(r.architecture(),"x64"),r.minClientVersion(),r.maxClientVersion());return ResponseEntity.created(URI.create("/api/v1/admin/gadgets/"+id+"/versions")).body(Map.of("id",vid));}catch(DuplicateKeyException e){return ResponseEntity.status(409).body(Map.of("error","version_exists"));}}
 @PostMapping("/versions/{versionId}/revoke") public ResponseEntity<?> revoke(@PathVariable String versionId){int n=db.update("UPDATE gadget_versions SET status='revoked',revoked_at=CURRENT_TIMESTAMP(6) WHERE id=? AND status<>'revoked'",versionId);if(n==0)return ResponseEntity.notFound().build();db.update("UPDATE device_gadget_cache SET status='revoked' WHERE gadget_version_id=?",versionId);return ResponseEntity.noContent().build();}
 private static String or(String s,String d){return s==null||s.isBlank()?d:s;}
}
